import json
import os
import re
import zipfile
from datetime import date
import xml.etree.ElementTree as ET


def collect_namespaces(xml_path: str) -> dict:
    ns = {}
    for event, elem in ET.iterparse(xml_path, events=["start-ns"]):
        prefix, uri = elem
        if prefix not in ns:
            ns[prefix] = uri
    return ns


def register_namespaces(ns_map: dict) -> None:
    for prefix, uri in ns_map.items():
        ET.register_namespace(prefix, uri)


def find_parent(root, target):
    for parent in root.iter():
        for child in parent:
            if child is target:
                return parent
    return None


def compute_international_age(birth_ymd: str, visit_ymd: str) -> int:
    by, bm, bd = map(int, birth_ymd.split("-"))
    vy, vm, vd = map(int, visit_ymd.split("-"))
    b = date(by, bm, bd)
    v = date(vy, vm, vd)
    age = v.year - b.year - (1 if (v.month, v.day) < (b.month, b.day) else 0)
    return age


def normalize_phone(phone: str) -> str:
    digits = re.sub(r"\D+", "", phone or "")
    # Expect 11 digits for KR mobile numbers like 010xxxxxxxx
    if len(digits) == 11:
        return f"{digits[0:3]}-{digits[3:7]}-{digits[7:11]}"
    # Fallback: return digits as-is if unexpected length
    return phone


def remove_all_linesegarray(root, lsa_tag):
    # Remove every linesegarray in the document to avoid stale layout cache.
    for lsa in list(root.iter(lsa_tag)):
        parent = find_parent(root, lsa)
        if parent is not None:
            parent.remove(lsa)


def rebuild_runs_and_replace(tree, ns_map, replacements):
    hp_ns = ns_map.get("hp")
    if not hp_ns:
        # If for some reason hp isn't in ns map, do nothing.
        return

    run_tag = f"{{{hp_ns}}}run"
    t_tag = f"{{{hp_ns}}}t"
    lsa_tag = f"{{{hp_ns}}}linesegarray"

    root = tree.getroot()

    # Replace placeholders, handling split placeholders within runs.
    for run in root.iter(run_tag):
        t_elems = list(run.iter(t_tag))
        if not t_elems:
            continue

        combined = "".join((t.text or "") for t in t_elems)
        if "{{" not in combined:
            continue

        new_text = combined
        for key, val in replacements.items():
            new_text = new_text.replace("{{" + key + "}}", val)

        # Only rewrite if something changed.
        if new_text != combined:
            t_elems[0].text = new_text
            for t in t_elems[1:]:
                parent = find_parent(root, t)
                if parent is not None:
                    parent.remove(t)

    # Aggressively remove all linesegarray elements.
    remove_all_linesegarray(root, lsa_tag)


def main():
    # Load patient data
    with open("/root/patient_intake.json", encoding="utf-8") as f:
        data = json.load(f)

    birth = data.get("생년월일", "")
    visit = data.get("방문일", "")

    age = compute_international_age(birth, visit)
    birth_with_age = f"{birth} ({age}세)" if birth else ""

    phone_norm = normalize_phone(data.get("회신전화", ""))

    # Placeholder mapping (must match template placeholders)
    replacements = {
        "환자명": str(data.get("환자명", "")),
        "생년월일": birth_with_age,
        "방문일": str(data.get("방문일", "")),
        "진료팀": str(data.get("진료팀", "")),
        "회신전화": str(phone_norm),
        "증상요약": str(data.get("증상요약", "")),
        "보험상태": str(data.get("보험상태", "")),
    }

    # Process all XML files under Contents/
    base_dir = "/tmp/hwpx_work"
    for dirpath, dirnames, filenames in os.walk(os.path.join(base_dir, "Contents")):
        for fn in filenames:
            if not fn.endswith(".xml"):
                continue
            xml_path = os.path.join(dirpath, fn)
            ns_map = collect_namespaces(xml_path)
            register_namespaces(ns_map)
            tree = ET.parse(xml_path)
            rebuild_runs_and_replace(tree, ns_map, replacements)
            tree.write(xml_path, xml_declaration=True, encoding="UTF-8")

    # Repackage to output hwpx
    out_path = "/root/clinic_intake_ready.hwpx"
    with zipfile.ZipFile(out_path, "w") as zout:
        # Ensure mimetype is first and stored (uncompressed) if present
        mimetype_path = os.path.join(base_dir, "mimetype")
        if os.path.exists(mimetype_path):
            zout.write(mimetype_path, "mimetype", compress_type=zipfile.ZIP_STORED)

        for dirpath, dirnames, filenames in os.walk(base_dir):
            for fn in filenames:
                filepath = os.path.join(dirpath, fn)
                arcname = os.path.relpath(filepath, base_dir)
                if arcname == "mimetype":
                    continue
                if arcname == "transform.py":
                    continue
                zout.write(filepath, arcname, compress_type=zipfile.ZIP_DEFLATED)


if __name__ == "__main__":
    main()

